<script setup lang="ts">
import { reactive,ref } from 'vue';import { useRouter } from 'vue-router';import { ElMessage } from '@/app/messages';import { register } from '@/api/user';import { readableError } from '@/api/errors'
const router=useRouter(),busy=ref(false),error=ref('');const form=reactive({userAccount:'',userPassword:'',checkPassword:'',invitationCode:''})
async function submit(){if(busy.value)return;error.value='';if(!form.invitationCode.trim()){error.value='请填写管理员提供的邀请码';return}if(form.userAccount.length<4){error.value='账号至少 4 位';return}if(form.userPassword.length<8){error.value='密码至少 8 位';return}if(form.userPassword!==form.checkPassword){error.value='两次输入的密码不一致';return}busy.value=true;try{await register({...form,invitationCode:form.invitationCode.trim()});ElMessage.success({ message: '注册成功，请登录' });await router.replace({path:'/login',query:{account:form.userAccount}})}catch(e){error.value=readableError(e)}finally{busy.value=false}}
</script>
<template><section><h1>凭邀请创建账号</h1><p class="hint">仅限受邀用户注册，请向管理员索取邀请码。账号至少 4 位，密码至少 8 位。</p><el-form label-position="top"><el-form-item label="邀请码"><el-input v-model="form.invitationCode" aria-label="邀请码" autocomplete="off" maxlength="64" placeholder="输入管理员提供的一次性邀请码"/></el-form-item><el-form-item label="账号"><el-input v-model="form.userAccount" aria-label="账号" autocomplete="username"/></el-form-item><el-form-item label="密码"><el-input v-model="form.userPassword" aria-label="密码" type="password" show-password autocomplete="new-password"/></el-form-item><el-form-item label="确认密码"><el-input v-model="form.checkPassword" aria-label="确认密码" type="password" show-password autocomplete="new-password" @keyup.enter="submit"/></el-form-item><p v-if="error" class="form-error" role="alert">{{error}}</p><el-button class="submit" type="primary" :loading="busy" @click="submit">凭邀请码注册</el-button></el-form><p class="switch">已有账号？<RouterLink to="/login">返回登录</RouterLink></p></section></template>
<style scoped>h1{font-size:24px;margin:0}.hint{color:var(--oj-text-muted);margin:8px 0 26px}.submit{width:100%;height:40px}.form-error{color:var(--oj-danger);margin:-4px 0 14px}.switch{text-align:center;color:var(--oj-text-muted);margin:22px 0 0}</style>
